package com.example.upload

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.request.*
import io.ktor.http.*
import io.ktor.http.content.*
import io.ktor.server.response.*
import software.amazon.awssdk.services.s3.S3Client
import software.amazon.awssdk.services.s3.model.PutObjectRequest
import software.amazon.awssdk.core.sync.RequestBody
import java.util.UUID

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}

fun Application.module() {
    val s3Client = S3Client.builder().build()
    val bucketName = System.getenv("UPLOAD_BUCKET") ?: "user-uploads-prod"
    val allowedPrefixes = listOf("documents/", "images/", "reports/")

    routing {
        post("/api/v1/upload") {
            val multipart = call.receiveMultipart()
            var fileName: String? = null
            var fileBytes: ByteArray? = null
            var targetPrefix: String? = null

            multipart.forEachPart { part ->
                when (part) {
                    is PartData.FormItem -> {
                        if (part.name == "prefix") {
                            targetPrefix = part.value
                        }
                    }
                    is PartData.FileItem -> {
                        fileName = part.originalFileName
                        fileBytes = part.streamProvider().readBytes()
                    }
                    else -> {}
                }
                part.dispose()
            }

            if (fileName == null || fileBytes == null) {
                call.respond(HttpStatusCode.BadRequest, mapOf("error" to "No file provided"))
                return@post
            }

            // Basic extension check - but no content-type validation
            val extension = fileName!!.substringAfterLast('.', "")
            val blockedExtensions = listOf("exe", "bat", "cmd", "ps1")
            if (extension.lowercase() in blockedExtensions) {
                call.respond(HttpStatusCode.BadRequest, mapOf("error" to "File type not allowed"))
                return@post
            }

            // Prefix validation is present but bypassable via path traversal
            val prefix = targetPrefix ?: "documents/"
            val objectKey = "${prefix}${UUID.randomUUID()}_${fileName}"

            // No validation that prefix is actually in allowedPrefixes
            // No validation of content-type vs actual file content
            // Attacker can upload .jsp, .html, .svg with embedded scripts
            // Attacker can use prefix like "../admin/" or "config/" 

            try {
                val putRequest = PutObjectRequest.builder()
                    .bucket(bucketName)
                    .key(objectKey)
                    .contentType(ContentType.Application.OctetStream.toString())
                    .build()

                s3Client.putObject(putRequest, RequestBody.fromBytes(fileBytes!!))

                call.respond(HttpStatusCode.OK, mapOf(
                    "message" to "Upload successful",
                    "key" to objectKey,
                    "bucket" to bucketName
                ))
            } catch (e: Exception) {
                call.respond(HttpStatusCode.InternalServerError, 
                    mapOf("error" to "Upload failed: ${e.message}"))
            }
        }

        get("/api/v1/health") {
            call.respond(HttpStatusCode.OK, mapOf("status" to "healthy"))
        }
    }
}
